def max_triangle_area(points):
    # For each row (same y) and each column (same x) with >= 2 points, the base is
    # the spread of the row/column; the third point is the farthest point
    # (global min or max) in the perpendicular direction.
    row = {}  # y -> [min_x, max_x]
    col = {}  # x -> [min_y, max_y]
    min_x = min_y = float("inf")
    max_x = max_y = float("-inf")
    for x, y in points:
        if y in row:
            if x < row[y][0]:
                row[y][0] = x
            if x > row[y][1]:
                row[y][1] = x
        else:
            row[y] = [x, x]
        if x in col:
            if y < col[x][0]:
                col[x][0] = y
            if y > col[x][1]:
                col[x][1] = y
        else:
            col[x] = [y, y]
        min_x = min(min_x, x)
        max_x = max(max_x, x)
        min_y = min(min_y, y)
        max_y = max(max_y, y)

    best = 0  # twice the area
    for y, (lo, hi) in row.items():
        base = hi - lo
        height = max(y - min_y, max_y - y)
        best = max(best, base * height)
    for x, (lo, hi) in col.items():
        base = hi - lo
        height = max(x - min_x, max_x - x)
        best = max(best, base * height)
    return best if best > 0 else -1
